import { getComponentByName } from '../utils/dataLoader.js';

const REACT_BITS_RAW = 'https://raw.githubusercontent.com/davidhdev/react-bits/main';

/**
 * Generate code to integrate React Bits components into existing frontend code
 */
export async function generateIntegrationCode(args) {
  const { 
    originalCode, 
    componentName, 
    integrationPoints = [], 
    techStack = 'js-css' 
  } = args;

  try {
    // Find component
    const component = getComponentByName(componentName);
    if (!component) {
      return {
        content: [
          {
            type: 'text',
            text: `Component "${componentName}" not found. Use search-react-bits-components to find available components.`
          }
        ]
      };
    }

    // Analyze original code
    const codeAnalysis = analyzeOriginalCode(originalCode);
    
    // Generate integration strategy
    const integrationStrategy = generateIntegrationStrategy(
      codeAnalysis, 
      component, 
      integrationPoints, 
      techStack
    );

    // Generate modified code
    const modifiedCode = generateModifiedCode(
      originalCode, 
      componentName, 
      integrationStrategy, 
      techStack
    );

    // Get component code
    const componentCode = await fetchComponentCode(componentName, component.category, techStack);

    // Format response
    const responseText = formatIntegrationResponse(
      originalCode,
      modifiedCode,
      componentCode,
      componentName,
      integrationStrategy,
      techStack
    );

    return {
      content: [
        {
          type: 'text',
          text: responseText
        }
      ]
    };

  } catch (error) {
    return {
      content: [
        {
          type: 'text',
          text: `Error generating integration code: ${error.message}`
        }
      ],
      isError: true
    };
  }
}

/**
 * Analyze original code structure
 */
function analyzeOriginalCode(code) {
  return {
    framework: detectFramework(code),
    hasImports: /import\s+/.test(code),
    hasExports: /export\s+/.test(code),
    components: extractComponentNames(code),
    styling: detectStyling(code),
    structure: analyzeStructure(code)
  };
}

/**
 * Detect framework from code
 */
function detectFramework(code) {
  if (/import.*react/i.test(code) || /from\s+['"]react['"]/.test(code)) return 'react';
  if (/import.*vue/i.test(code) || /@vue/.test(code)) return 'vue';
  if (/import.*angular/i.test(code) || /@angular/.test(code)) return 'angular';
  return 'vanilla';
}

/**
 * Extract component names from code
 */
function extractComponentNames(code) {
  const names = [];
  
  // Function components
  const functionMatches = code.match(/(?:function|const)\s+([A-Z]\w*)/g);
  if (functionMatches) {
    functionMatches.forEach(match => {
      const name = match.match(/(?:function|const)\s+([A-Z]\w*)/)[1];
      names.push(name);
    });
  }

  // Class components
  const classMatches = code.match(/class\s+([A-Z]\w*)/g);
  if (classMatches) {
    classMatches.forEach(match => {
      const name = match.match(/class\s+([A-Z]\w*)/)[1];
      names.push(name);
    });
  }

  return names;
}

/**
 * Detect styling approach
 */
function detectStyling(code) {
  if (/className=["'][^"']*(?:bg-|text-|p-|m-)/.test(code)) return 'tailwind';
  if (/styled\.\w+/.test(code)) return 'styled-components';
  if (/@emotion/.test(code)) return 'emotion';
  return 'css';
}

/**
 * Analyze code structure
 */
function analyzeStructure(code) {
  const structure = {
    hasJSX: /<\w+/.test(code),
    hasHooks: /use\w+\(/.test(code),
    hasState: /useState|useReducer/.test(code),
    hasEffects: /useEffect/.test(code),
    hasEventHandlers: /on\w+\s*=/.test(code),
    elements: []
  };

  // Detect common elements
  const elementPatterns = {
    button: /<button|<Button/g,
    div: /<div/g,
    card: /card|Card/g,
    list: /<ul|<ol|<li/g,
    form: /<form|<input/g
  };

  Object.entries(elementPatterns).forEach(([element, pattern]) => {
    const matches = code.match(pattern);
    if (matches) {
      structure.elements.push({ type: element, count: matches.length });
    }
  });

  return structure;
}

/**
 * Generate integration strategy
 */
function generateIntegrationStrategy(analysis, component, integrationPoints, techStack) {
  const strategy = {
    approach: 'wrap', // wrap, replace, or enhance
    targetElements: [],
    imports: [],
    modifications: [],
    dependencies: []
  };

  // Determine approach based on component type
  if (component.category === 'backgrounds') {
    strategy.approach = 'wrap';
    strategy.targetElements = ['root', 'container'];
  } else if (component.category === 'components') {
    strategy.approach = 'replace';
    strategy.targetElements = findReplaceableElements(analysis, component.name);
  } else {
    strategy.approach = 'enhance';
    strategy.targetElements = findEnhanceableElements(analysis, component.name);
  }

  // Generate imports
  strategy.imports = generateImports(component.name, techStack);

  // Generate dependencies
  strategy.dependencies = generateDependencies(component.name, component.category, techStack);

  return strategy;
}

/**
 * Find elements that can be replaced
 */
function findReplaceableElements(analysis, componentName) {
  const replaceMap = {
    'stack': ['card', 'div'],
    'dock': ['nav', 'menu'],
    'spotlight-card': ['card', 'div'],
    'infinite-scroll': ['list', 'div']
  };

  return replaceMap[componentName] || ['div'];
}

/**
 * Find elements that can be enhanced
 */
function findEnhanceableElements(analysis, componentName) {
  const enhanceMap = {
    'bounce-cards': ['button', 'card'],
    'elastic-slider': ['input', 'slider'],
    'tilted-card': ['card', 'div']
  };

  return enhanceMap[componentName] || ['div'];
}

/**
 * Generate import statements
 */
function generateImports(componentName, techStack) {
  const componentPath = `./${capitalizeFirst(componentName)}`;
  const extension = techStack.includes('ts') ? '.tsx' : '.jsx';
  
  return [
    `import ${capitalizeFirst(componentName)} from '${componentPath}${extension}';`
  ];
}

/**
 * Generate dependencies
 */
function generateDependencies(componentName, category, techStack) {
  const baseDeps = ['react', 'react-dom'];
  
  // Add common animation dependencies
  if (category === 'animations' || category === 'components') {
    baseDeps.push('framer-motion');
  }

  // Add 3D dependencies for specific components
  if (['model-viewer', 'fluid-glass', 'orb'].includes(componentName)) {
    baseDeps.push('three', '@react-three/fiber', '@react-three/drei');
  }

  // Add tech stack specific dependencies
  if (techStack.includes('tailwind')) {
    baseDeps.push('tailwindcss');
  }

  return baseDeps;
}

/**
 * Generate modified code
 */
function generateModifiedCode(originalCode, componentName, strategy, techStack) {
  let modifiedCode = originalCode;

  // Add imports at the top
  const importSection = strategy.imports.join('\n') + '\n\n';
  
  // Find where to insert imports
  const importMatch = modifiedCode.match(/^(import.*\n)*/m);
  if (importMatch) {
    modifiedCode = modifiedCode.replace(importMatch[0], importMatch[0] + importSection);
  } else {
    modifiedCode = importSection + modifiedCode;
  }

  // Apply integration based on strategy
  switch (strategy.approach) {
    case 'wrap':
      modifiedCode = wrapWithComponent(modifiedCode, componentName);
      break;
    case 'replace':
      modifiedCode = replaceElements(modifiedCode, componentName, strategy.targetElements);
      break;
    case 'enhance':
      modifiedCode = enhanceElements(modifiedCode, componentName, strategy.targetElements);
      break;
  }

  return modifiedCode;
}

/**
 * Wrap existing code with component
 */
function wrapWithComponent(code, componentName) {
  const componentTag = capitalizeFirst(componentName);
  
  // Find the main return statement
  const returnMatch = code.match(/(return\s*\(?\s*)([\s\S]*?)(\s*\)?;?\s*}?\s*$)/);
  
  if (returnMatch) {
    const [, returnStart, content, returnEnd] = returnMatch;
    const wrappedContent = `${returnStart}<${componentTag}>\n${content}\n</${componentTag}>${returnEnd}`;
    return code.replace(returnMatch[0], wrappedContent);
  }
  
  return code;
}

/**
 * Replace elements with component
 */
function replaceElements(code, componentName, targetElements) {
  let modifiedCode = code;
  const componentTag = capitalizeFirst(componentName);
  
  // Replace first occurrence of target elements
  targetElements.forEach(element => {
    const pattern = new RegExp(`<${element}([^>]*)>([\\s\\S]*?)</${element}>`, 'i');
    const match = modifiedCode.match(pattern);
    
    if (match) {
      const [fullMatch, attributes, content] = match;
      const replacement = `<${componentTag}${attributes}>\n${content}\n</${componentTag}>`;
      modifiedCode = modifiedCode.replace(fullMatch, replacement);
    }
  });
  
  return modifiedCode;
}

/**
 * Enhance elements with component
 */
function enhanceElements(code, componentName, targetElements) {
  let modifiedCode = code;
  const componentTag = capitalizeFirst(componentName);
  
  // Wrap target elements with component
  targetElements.forEach(element => {
    const pattern = new RegExp(`(<${element}[^>]*>)([\\s\\S]*?)(</${element}>)`, 'gi');
    modifiedCode = modifiedCode.replace(pattern, (match, openTag, content, closeTag) => {
      return `<${componentTag}>\n${openTag}${content}${closeTag}\n</${componentTag}>`;
    });
  });
  
  return modifiedCode;
}

/**
 * Fetch component code (simplified version)
 */
async function fetchComponentCode(componentName, category, techStack) {
  try {
    const versionDir = getVersionDirectory(techStack);
    const categoryDir = getCategoryDirectory(category);
    const componentPath = `${versionDir}/${categoryDir}/${componentName}/${componentName}.jsx`;
    
    const response = await fetch(`${REACT_BITS_RAW}/${componentPath}`);
    if (response.ok) {
      return await response.text();
    }
  } catch (error) {
    // Return placeholder if fetch fails
  }
  
  return generatePlaceholderComponent(componentName);
}

/**
 * Get version directory
 */
function getVersionDirectory(techStack) {
  const versionMap = {
    'js-css': 'src/content',
    'js-tailwind': 'src/tailwind',
    'ts-css': 'src/ts-default',
    'ts-tailwind': 'src/ts-tailwind'
  };
  
  return versionMap[techStack] || 'src/content';
}

/**
 * Get category directory
 */
function getCategoryDirectory(category) {
  const categoryMap = {
    'animations': 'Animations',
    'text-animations': 'TextAnimations',
    'components': 'Components',
    'backgrounds': 'Backgrounds'
  };
  
  return categoryMap[category] || 'Components';
}

/**
 * Generate placeholder component
 */
function generatePlaceholderComponent(componentName) {
  return `import React from 'react';

export default function ${capitalizeFirst(componentName)}({ children, ...props }) {
  return (
    <div className="${componentName}-container" {...props}>
      {children}
    </div>
  );
}`;
}

/**
 * Format integration response
 */
function formatIntegrationResponse(originalCode, modifiedCode, componentCode, componentName, strategy, techStack) {
  let output = `# Integration Code for ${capitalizeFirst(componentName)}\n\n`;
  
  output += `**Component:** ${componentName}\n`;
  output += `**Tech Stack:** ${techStack}\n`;
  output += `**Integration Approach:** ${strategy.approach}\n`;
  output += `**Target Elements:** ${strategy.targetElements.join(', ')}\n\n`;

  // Dependencies
  output += `## Required Dependencies\n\n`;
  output += `\`\`\`bash\n`;
  output += `npm install ${strategy.dependencies.join(' ')}\n`;
  output += `\`\`\`\n\n`;

  // Component file
  output += `## Component File\n\n`;
  output += `Create \`${capitalizeFirst(componentName)}.${techStack.includes('ts') ? 'tsx' : 'jsx'}\`:\n\n`;
  output += `\`\`\`jsx\n${componentCode}\n\`\`\`\n\n`;

  // Modified code
  output += `## Your Modified Code\n\n`;
  output += `\`\`\`jsx\n${modifiedCode}\n\`\`\`\n\n`;

  // Integration steps
  output += `## Integration Steps\n\n`;
  output += `1. **Install dependencies** using the command above\n`;
  output += `2. **Create component file** with the provided code\n`;
  output += `3. **Replace your existing code** with the modified version\n`;
  output += `4. **Test the integration** and adjust props as needed\n\n`;

  // Customization tips
  output += `## Customization Tips\n\n`;
  output += `- Adjust component props to match your design requirements\n`;
  output += `- Add custom CSS classes for additional styling\n`;
  output += `- Consider performance implications for complex animations\n`;
  output += `- Test on different devices and screen sizes\n\n`;

  // Next steps
  output += `## Next Steps\n\n`;
  output += `- Use \`get-react-bits-demo --componentName ${componentName}\` for usage examples\n`;
  output += `- Use \`get-react-bits-install-guide --componentName ${componentName}\` for detailed setup\n`;
  output += `- Explore similar components with \`search-react-bits-components\`\n`;

  return output;
}

/**
 * Utility function
 */
function capitalizeFirst(str) {
  return str.charAt(0).toUpperCase() + str.slice(1);
}
